DO $township_gap$
DECLARE
    v_target_id constant bigint := 5142;
    v_expected_name constant text := 'ခရမ်းမြို့နယ်';
    v_mimu_pcode constant text := 'MMR013026';
    v_mimu geometry;
    v_approved geometry;
    v_before core.core_admin_areas%ROWTYPE;
    v_after core.core_admin_areas%ROWTYPE;
    v_before_other jsonb;
    v_after_other jsonb;
    v_current_union geometry;
    v_other_union geometry;
    v_current_remaining geometry;
    v_raw_safe_patch geometry;
    v_safe_patch geometry;
    v_new_geom geometry;
    v_added geometry;
    v_removed geometry;
    v_area_added_m2 double precision;
    v_removed_m2 double precision;
    v_outside_mimu_m2 double precision;
    v_outside_approved_m2 double precision;
    v_precovered_m2 double precision;
    v_new_overlap_m2 double precision;
    v_boundary_collar_m2 double precision;
BEGIN
    SELECT aa.*
    INTO v_before
    FROM core.core_admin_areas AS aa
    INNER JOIN ref.ref_admin_levels AS al ON al.id = aa.admin_level_id
    WHERE aa.id = v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(al.code)) = 'township'
    FOR UPDATE OF aa;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Target % is missing or no longer an active township', v_target_id;
    END IF;
    IF v_before.canonical_name IS DISTINCT FROM v_expected_name THEN
        RAISE EXCEPTION 'Target % name changed after backup: %', v_target_id, v_before.canonical_name;
    END IF;
    IF v_before.geom IS NULL OR ST_IsEmpty(v_before.geom) OR NOT ST_IsValid(v_before.geom) THEN
        RAISE EXCEPTION 'Target % has unusable current geometry', v_target_id;
    END IF;
    IF ST_SRID(v_before.geom) <> 4326
       OR ST_GeometryType(v_before.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % current geometry type/SRID is unsafe', v_target_id;
    END IF;

    v_before_other := to_jsonb(v_before) - ARRAY['geom', 'updated_at'];
    v_mimu := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(decode('', 'base64')),
                    4326
                )
            ),
            3
        )
    );
    v_approved := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_SetSRID(
                    ST_GeomFromWKB(
                        decode('', 'base64')
                    ),
                    4326
                )
            ),
            3
        )
    );

    IF v_mimu IS NULL OR ST_IsEmpty(v_mimu) OR NOT ST_IsValid(v_mimu) THEN
        RAISE EXCEPTION 'MIMU geometry is unusable for target %', v_target_id;
    END IF;
    IF v_approved IS NULL OR ST_IsEmpty(v_approved) OR NOT ST_IsValid(v_approved) THEN
        RAISE EXCEPTION 'Approved AUTO_UPDATE patch is unusable for target %', v_target_id;
    END IF;

    -- Recomputed immediately before this row update. Prior rows in this transaction
    -- are visible here, so the union advances after every successful patch.
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_current_union
    FROM core.core_admin_areas AS aa
    INNER JOIN ref.ref_admin_levels AS al ON al.id = aa.admin_level_id
    WHERE aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(al.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);

    v_current_remaining := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_Intersection(
                    v_mimu,
                    ST_Difference(v_mimu, v_current_union)
                )
            ),
            3
        )
    );
    -- Cap the latest live gap by the already approved AUTO_UPDATE surface.
    v_raw_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Intersection(v_approved, v_current_remaining)),
            3
        )
    );

    IF v_raw_safe_patch IS NULL
       OR ST_IsEmpty(v_raw_safe_patch)
       OR ST_Area(ST_Transform(v_raw_safe_patch, 6933)) < 100.0 THEN
        INSERT INTO _township_gap_batch_results (
            township_id, canonical_name, mimu_pcode, status, area_added_m2, reason
        )
        VALUES (
            v_target_id,
            v_before.canonical_name,
            v_mimu_pcode,
            'skipped',
            0,
            'latest approved live-gap intersection is empty or below 100 m2'
        );
        RETURN;
    END IF;

    -- Keep every original polygon component verbatim. An inward 1e-11 degree
    -- (~micrometre) collar on the additive surface prevents shared-edge
    -- collection invalidity without materially changing approved coverage.
    v_safe_patch := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(
                ST_Buffer(v_raw_safe_patch, -1e-11)
            ),
            3
        )
    );
    v_boundary_collar_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(
                    ST_Difference(v_raw_safe_patch, v_safe_patch),
                    3
                ),
                6933
            )
        ),
        0
    );
    IF v_safe_patch IS NULL
       OR ST_IsEmpty(v_safe_patch)
       OR ST_Area(ST_Transform(v_safe_patch, 6933)) < 100.0 THEN
        RAISE EXCEPTION 'Target % became empty/below 100 m2 after boundary collar', v_target_id;
    END IF;
    IF v_boundary_collar_m2 > 1.0 THEN
        RAISE EXCEPTION 'Target % boundary collar removed % m2', v_target_id, v_boundary_collar_m2;
    END IF;

    v_new_geom := ST_Multi(
        ST_CollectionExtract(
            ST_Collect(v_before.geom, v_safe_patch),
            3
        )
    );
    v_added := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_new_geom, v_before.geom)),
            3
        )
    );
    v_removed := ST_Multi(
        ST_CollectionExtract(
            ST_MakeValid(ST_Difference(v_before.geom, v_new_geom)),
            3
        )
    );
    v_area_added_m2 := coalesce(ST_Area(ST_Transform(v_added, 6933)), 0);
    v_removed_m2 := coalesce(ST_Area(ST_Transform(v_removed, 6933)), 0);
    v_outside_mimu_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_mimu), 6933)),
        0
    );
    v_outside_approved_m2 := coalesce(
        ST_Area(ST_Transform(ST_Difference(v_added, v_approved), 6933)),
        0
    );
    v_precovered_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_current_union), 3),
                6933
            )
        ),
        0
    );
    SELECT ST_UnaryUnion(ST_Collect(aa.geom))
    INTO v_other_union
    FROM core.core_admin_areas AS aa
    INNER JOIN ref.ref_admin_levels AS al ON al.id = aa.admin_level_id
    WHERE aa.id <> v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(al.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        RAISE EXCEPTION 'Target % generated invalid/empty new geometry', v_target_id;
    END IF;
    IF ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % generated wrong type/SRID', v_target_id;
    END IF;
    IF v_removed_m2 > 0.01 THEN
        RAISE EXCEPTION 'Target % would remove % m2', v_target_id, v_removed_m2;
    END IF;
    IF v_outside_mimu_m2 > 0.01 THEN
        RAISE EXCEPTION 'Target % adds % m2 outside MIMU', v_target_id, v_outside_mimu_m2;
    END IF;
    IF v_outside_approved_m2 > 0.01 THEN
        RAISE EXCEPTION 'Target % adds % m2 outside approved patch', v_target_id, v_outside_approved_m2;
    END IF;
    IF v_precovered_m2 > 0.01 THEN
        RAISE EXCEPTION 'Target % adds % m2 that was already covered', v_target_id, v_precovered_m2;
    END IF;
    IF v_new_overlap_m2 > 100.0 THEN
        RAISE EXCEPTION 'Target % creates % m2 positive-area overlap', v_target_id, v_new_overlap_m2;
    END IF;
    IF v_area_added_m2 < 100.0 THEN
        RAISE EXCEPTION 'Target % unexpectedly adds less than 100 m2', v_target_id;
    END IF;

    -- Deliberately update geom only. Any updated_at change may only come from
    -- an existing automatic trigger; this repair does not set it.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.*
    INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other THEN
        RAISE EXCEPTION 'Target % changed a forbidden non-geometry column', v_target_id;
    END IF;
    IF NOT ST_IsEmpty(ST_Difference(v_before.geom, v_after.geom)) THEN
        RAISE EXCEPTION 'Target % post-update geometry no longer covers old geometry', v_target_id;
    END IF;
    IF NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update geometry validation', v_target_id;
    END IF;

    INSERT INTO _township_gap_batch_results (
        township_id, canonical_name, mimu_pcode, status, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id,
        v_after.canonical_name,
        v_mimu_pcode,
        'updated',
        v_area_added_m2,
        v_new_overlap_m2,
        'approved live-gap patch; original geometry preserved verbatim'
    );
END
