    INTO v_other_union
    FROM core.core_admin_areas AS aa
    INNER JOIN ref.ref_admin_levels AS al ON al.id = aa.admin_level_id
    WHERE aa.id <> v_target_id
      AND aa.is_active IS TRUE
      AND aa.deleted_at IS NULL
      AND lower(btrim(al.code)) = 'township'
      AND aa.geom IS NOT NULL
      AND NOT ST_IsEmpty(aa.geom)
      AND ST_IsValid(aa.geom);
    v_new_overlap_m2 := coalesce(
        ST_Area(
            ST_Transform(
                ST_CollectionExtract(ST_Intersection(v_added, v_other_union), 3),
                6933
            )
        ),
        0
    );

    IF v_new_geom IS NULL OR ST_IsEmpty(v_new_geom) OR NOT ST_IsValid(v_new_geom) THEN
        RAISE EXCEPTION 'Target % generated invalid/empty new geometry', v_target_id;
    END IF;
    IF ST_SRID(v_new_geom) <> 4326
       OR ST_GeometryType(v_new_geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % generated wrong type/SRID', v_target_id;
    END IF;
    IF v_removed_m2 > 0.01 THEN
        RAISE EXCEPTION 'Target % would remove % m2', v_target_id, v_removed_m2;
    END IF;
    IF v_outside_mimu_m2 > 0.01 THEN
        RAISE EXCEPTION 'Target % adds % m2 outside MIMU', v_target_id, v_outside_mimu_m2;
    END IF;
    IF v_outside_approved_m2 > 0.01 THEN
        RAISE EXCEPTION 'Target % adds % m2 outside approved patch', v_target_id, v_outside_approved_m2;
    END IF;
    IF v_precovered_m2 > 0.01 THEN
        RAISE EXCEPTION 'Target % adds % m2 that was already covered', v_target_id, v_precovered_m2;
    END IF;
    IF v_new_overlap_m2 > 100.0 THEN
        RAISE EXCEPTION 'Target % creates % m2 positive-area overlap', v_target_id, v_new_overlap_m2;
    END IF;
    IF v_area_added_m2 < 100.0 THEN
        RAISE EXCEPTION 'Target % unexpectedly adds less than 100 m2', v_target_id;
    END IF;

    -- Deliberately update geom only. Any updated_at change may only come from
    -- an existing automatic trigger; this repair does not set it.
    UPDATE core.core_admin_areas
    SET geom = v_new_geom::geometry(MultiPolygon, 4326)
    WHERE id = v_target_id;

    SELECT aa.*
    INTO v_after
    FROM core.core_admin_areas AS aa
    WHERE aa.id = v_target_id;
    v_after_other := to_jsonb(v_after) - ARRAY['geom', 'updated_at'];
    IF v_after_other IS DISTINCT FROM v_before_other THEN
        RAISE EXCEPTION 'Target % changed a forbidden non-geometry column', v_target_id;
    END IF;
    IF NOT ST_IsEmpty(ST_Difference(v_before.geom, v_after.geom)) THEN
        RAISE EXCEPTION 'Target % post-update geometry no longer covers old geometry', v_target_id;
    END IF;
    IF NOT ST_IsValid(v_after.geom)
       OR ST_IsEmpty(v_after.geom)
       OR ST_SRID(v_after.geom) <> 4326
       OR ST_GeometryType(v_after.geom) <> 'ST_MultiPolygon' THEN
        RAISE EXCEPTION 'Target % failed post-update geometry validation', v_target_id;
    END IF;

    INSERT INTO _township_gap_batch_results (
        township_id, canonical_name, mimu_pcode, status, area_added_m2,
        new_overlap_m2, reason
    )
    VALUES (
        v_target_id,
        v_after.canonical_name,
        v_mimu_pcode,
        'updated',
        v_area_added_m2,
        v_new_overlap_m2,
        'approved live-gap patch; original geometry preserved verbatim'
    );
END
